"""Exact loopback HTTP API and signal-driven, drained server lifecycle."""

from __future__ import annotations

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import signal
import socket
import sys
import threading

from .domain import (
    APIError, Clock, RateLimiter, decode_json, format_timestamp, json_bytes,
    valid_slug, validate_clock,
)
from .storage import Storage


class Server(ThreadingHTTPServer):
    # Join every handler before the caller closes the shared database.
    daemon_threads = False
    block_on_close = True

    def __init__(self, storage: Storage, admin_key: str, port: int,
                 rate_limit: int = 60, fake_clock: int | None = None):
        self.storage = storage
        self.admin_key = admin_key
        self.clock = Clock(fake_clock)
        self.limiter = RateLimiter(rate_limit)
        self._active = set()
        self._active_lock = threading.Lock()
        super().__init__(("127.0.0.1", port), Handler)
        self.base_url = f"http://127.0.0.1:{self.server_port}"

    def process_request(self, request, client_address):
        with self._active_lock:
            self._active.add(request)
        try:
            super().process_request(request, client_address)
        except BaseException:
            with self._active_lock:
                self._active.discard(request)
            raise

    def process_request_thread(self, request, client_address):
        try:
            super().process_request_thread(request, client_address)
        finally:
            with self._active_lock:
                self._active.discard(request)

    def server_close(self):
        # Call after shutdown(): no more sockets can enter the active set.
        with self._active_lock:
            for request in self._active:
                try:
                    request.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass
        super().server_close()


class Handler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.0"

    def __getattr__(self, name):
        # BaseHTTPRequestHandler otherwise sends HTML 501 for extension methods.
        if name.startswith("do_"):
            return self._dispatch
        raise AttributeError(name)

    def log_message(self, format, *args):
        # No per-request logs, and in particular no stdout output.
        pass

    def _route(self):
        # self.path is normalized by the stdlib for leading '//'; do not use it.
        path = self.requestline.split()[1].split("?", 1)[0]
        method = self.command
        if (method, path) == ("GET", "/healthz"):
            return "health", None
        if (method, path) == ("POST", "/v1/tokens"):
            return "token", None
        if path == "/v1/links" and method in ("POST", "GET"):
            return ("create" if method == "POST" else "list"), None
        if (method, path) == ("POST", "/v1/admin/clock") and self.server.clock.is_fake:
            return "clock", None
        if path.startswith("/v1/links/") and method in ("GET", "DELETE"):
            slug = path[len("/v1/links/"):]
            if valid_slug(slug):
                return ("get" if method == "GET" else "delete"), slug
        if method == "GET" and path.startswith("/") and valid_slug(path[1:]):
            return "resolve", path[1:]
        raise APIError(404, "not_found", "Route not found")

    def _authenticate(self, route):
        if route in ("token", "clock"):
            if self.headers.get_all("X-Admin-Key") != [self.server.admin_key]:
                raise APIError(401, "unauthorized", "Invalid admin key")
        elif route in ("create", "list", "get", "delete"):
            values = self.headers.get_all("Authorization", [])
            if len(values) != 1 or not values[0].startswith("Bearer "):
                raise APIError(401, "unauthorized", "Expected Bearer token")
            return self.server.storage.authenticate(values[0][len("Bearer "):])
        return None

    def _body_length(self):
        values = self.headers.get_all("Content-Length", [])
        if not values:
            length = 0
        elif len(values) == 1 and values[0].isascii() and values[0].isdigit():
            length = int(values[0])
        else:
            raise APIError(400, "invalid_request", "Invalid Content-Length")
        if length > 8192:
            raise APIError(413, "payload_too_large", "Body exceeds 8192 bytes",
                           {"Connection": "close"})
        if self.headers.get("Transfer-Encoding") is not None:
            raise APIError(400, "invalid_request", "Unsupported body framing")
        return length

    def _write(self, status, body=None, headers=None):
        payload = b"" if body is None else json_bytes(body)
        self.send_response(status)
        if body is not None:
            self.send_header("Content-Type", "application/json")
        self.send_header("Content-Length", str(len(payload)))
        for key, value in (headers or {}).items():
            if key == "Location":
                # Preserve Latin-1 wire compatibility where possible. For other
                # Unicode URLs emit the original value's UTF-8 octets, without
                # percent-encoding, IDNA, or any URL normalization.
                try:
                    value.encode("latin-1")
                except UnicodeEncodeError:
                    value = value.encode("utf-8").decode("latin-1")
            self.send_header(key, value)
        self.end_headers()
        self.wfile.write(payload)

    def _dispatch(self):
        # HTTP/1.0 closes even when an ignored body is left unread.
        self.close_connection = True
        try:
            route, slug = self._route()
            now = self.server.clock.now()
            owner = self._authenticate(route)
            if owner is not None:
                self.server.limiter.check(owner, now)
            length = self._body_length()
            body = None
            if route in ("create", "clock"):
                raw = self.rfile.read(length)
                if len(raw) != length:
                    raise APIError(400, "invalid_json", "Incomplete JSON body")
                body = decode_json(raw)
            storage = self.server.storage
            base_url = self.server.base_url
            if route == "health":
                self._write(200, {"status": "ok"})
            elif route == "token":
                self._write(201, storage.issue_token(now))
            elif route == "create":
                self._write(201, storage.create_link(owner, body, now, base_url))
            elif route == "list":
                self._write(200, storage.list_links(owner, base_url))
            elif route == "get":
                self._write(200, storage.get_link(owner, slug, base_url))
            elif route == "delete":
                storage.delete_link(owner, slug)
                self._write(204)
            elif route == "resolve":
                self._write(302, headers={"Location": storage.resolve(slug, now)})
            elif route == "clock":
                instant = self.server.clock.set(validate_clock(body))
                self._write(200, {"now": format_timestamp(instant)})
        except APIError as error:
            self._write(error.status, error.body(), error.headers)
        except (BrokenPipeError, ConnectionResetError, ConnectionAbortedError):
            pass
        except Exception as error:
            print(f"Request failed: {error}", file=sys.stderr)
            self._write(500, APIError(500, "internal", "Internal server error").body())


def run(args) -> int:
    """Block on the main thread; fake_clock is parsed integer seconds or None."""
    storage = None
    server = None
    try:
        storage = Storage(args.db)
        server = Server(storage, args.admin_key, args.port,
                        args.rate_limit, args.fake_clock)
    except Exception as error:
        if storage is not None:
            storage.close()
        print(f"Cannot start server: {error}", file=sys.stderr)
        return 3

    stop_requested = False

    def request_stop(signum, frame):
        nonlocal stop_requested
        stop_requested = True

    previous = {}
    worker = threading.Thread(target=server.serve_forever,
                              kwargs={"poll_interval": 0.05})
    started = False
    try:
        for name in ("SIGINT", "SIGTERM", "SIGBREAK"):
            sig = getattr(signal, name, None)
            if sig is not None:
                previous[sig] = signal.signal(sig, request_stop)
        worker.start()
        started = True
        print(f"LISTENING {server.base_url}", flush=True)
        while not stop_requested and worker.is_alive():
            worker.join(0.05)
        return 0
    finally:
        if started:
            # Main thread only: shutdown must not run in serve_forever's thread.
            server.shutdown()
            worker.join()
        server.server_close()
        storage.close()
        for sig, handler in previous.items():
            signal.signal(sig, handler)

